Use `pg` (node-postgres). `Pool` handles connection reuse.

```bash
npm install pg
```

```js
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // or individual fields:
  // host, port, database, user, password

  max: 20,                  // max connections in pool
  min: 2,                   // keep alive minimum
  idleTimeoutMillis: 30000, // close idle conn after 30s
  connectionTimeoutMillis: 2000, // fail if no conn available in 2s
  allowExitOnIdle: false,   // don't let pool drain on idle
});

// Error on idle clients — prevents silent crashes
pool.on('error', (err, client) => {
  console.error('Idle client error:', err);
  process.exit(-1); // or alert + let process manager restart
});
```

**Query with proper handling:**

```js
async function query(text, params) {
  const client = await pool.connect();
  try {
    const res = await client.query(text, params);
    return res;
  } finally {
    client.release(); // always release, even on error
  }
}
```

**Or simpler — use `pool.query` for one-shot queries:**

```js
// Pool auto-acquires and releases client
const res = await pool.query('SELECT * FROM users WHERE id = $1', [userId]);
```

Use `pool.query` when no transaction needed. Use `pool.connect()` + manual `release()` for transactions or multi-statement sequences.

**Transaction pattern:**

```js
async function withTransaction(fn) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const result = await fn(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;
  } finally {
    client.release();
  }
}

// Usage
await withTransaction(async (client) => {
  await client.query('UPDATE accounts SET balance = balance - $1 WHERE id = $2', [amount, fromId]);
  await client.query('UPDATE accounts SET balance = balance + $1 WHERE id = $2', [amount, toId]);
});
```

**Shutdown clean:**

```js
process.on('SIGTERM', async () => {
  await pool.end(); // drain pool before exit
});
```

Key config values depend on DB server `max_connections` — `pool.max` across all app instances must stay under that limit.
